<?php
defined('ABSPATH') || exit;
function dp_page_url($slug) { $p=get_page_by_path($slug); return $p?get_permalink($p):home_url('/#'.$slug); }
function dp_page_heading($title,$label='DP Technical Solution'){ ?>
<div class="page-heading"><div class="wrap"><div class="breadcrumb"><a href="<?php echo esc_url(home_url('/')); ?>">Trang chủ</a> / <?php echo esc_html($title); ?></div><span class="eyebrow"><?php echo esc_html($label); ?></span><h1><?php echo esc_html($title); ?></h1></div></div><?php }
function dp_news_card(){ ?><article class="card news-card"><a href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail())the_post_thumbnail('large',['loading'=>'lazy']); ?><div class="card-body"><p class="post-meta"><?php echo esc_html(get_the_date()); ?></p><h2><?php the_title(); ?></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),28)); ?></p><span class="card-bottom">Đọc bài viết →</span></div></a></article><?php }
function dp_render_business_page($kind){get_header();while(have_posts()){the_post(); ?>
<main id="main"><?php dp_page_heading(get_the_title()); ?><div class="wrap section page-layout"><article class="page-article"><?php if(has_post_thumbnail())the_post_thumbnail('large',['class'=>'page-cover']); ?><div class="entry-content"><?php the_content();wp_link_pages(); ?></div><?php if($kind==='contact')dp_contact(); ?></article><aside class="page-sidebar" aria-label="Thông tin liên quan"><div class="sidebar-box"><h2>Khám phá DP</h2><nav><?php foreach(['gioi-thieu'=>'Giới thiệu','phu-tung'=>'Phụ tùng','dich-vu'=>'Dịch vụ','giai-phap'=>'Giải pháp','tin-tuc'=>'Tin tức','lien-he'=>'Liên hệ'] as $slug=>$label){ ?><a href="<?php echo esc_url(dp_page_url($slug)); ?>" <?php if(get_post_field('post_name',get_the_ID())===$slug)echo 'aria-current="page"'; ?>><?php echo esc_html($label); ?> →</a><?php } ?></nav></div><div class="sidebar-box sidebar-help"><h2>Cần tư vấn kỹ thuật?</h2><p>Chia sẻ yêu cầu thiết bị, phụ tùng hoặc hệ thống của bạn với DP.</p><a class="btn" href="<?php echo esc_url($kind==='contact'?'#lien-he':dp_page_url('lien-he')); ?>">Liên hệ với DP →</a></div></aside></div></main><?php }get_footer();}
add_action('wp_enqueue_scripts',function(){wp_enqueue_style('dp-pages',get_theme_file_uri('assets/pages.css'),['dp-typography'],(string)filemtime(get_theme_file_path('assets/pages.css')));});
